package com.abhishek.ecommerce.user;
import jakarta.persistence.*;import java.util.UUID;
@Entity @Table(name="users") public class User{@Id @GeneratedValue(strategy=GenerationType.UUID) UUID id;@Column(nullable=false,unique=true)String email;@Column(nullable=false)String password;String name;@Enumerated(EnumType.STRING)Role role=Role.CUSTOMER;public UUID getId(){return id;}public String getEmail(){return email;}public void setEmail(String v){email=v;}public String getPassword(){return password;}public void setPassword(String v){password=v;}public String getName(){return name;}public void setName(String v){name=v;}public Role getRole(){return role;}public void setRole(Role v){role=v;}}